content.content:
 M .gitignore
src/book.sh:2:# book.sh ROOM DATE START END WHO: add a booking unless the room is taken at that time.
src/book.sh:8:limit=$(date -u -d "$today +90 days" +%Y-%m-%d)
src/lib/slots.sh:3:to_min() { local h=${1%%:*} m=${1##*:}; echo $(( 10#$h * 60 + 10#$m )); }
README.md:2:会議室の予約。`bash src/book.sh <部屋> <日付> <開始> <終了> <名前>` で予約し、`bash src/list.sh [日付]` で一覧を出す。`src/remind.sh` は一覧の出力を読んでリマインドを作る。
docs/design/booking-rules.md:3:対応する実装: src/lib/slots.sh, src/book.sh
docs/design/booking-rules.md:13:- 予約できるのは当日から 60 日先まで。それより先は exit 2、stderr に `too far ahead`
docs/decisions/0004-room-capacity-in-rooms-tsv.md:6:予約の人数は src/book.sh の 6 番目の引数で受け（省略時 1）、定員を超える予約は exit 1 で断る。
spec/slots.spec.sh:4:overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
spec/slots.spec.sh:5:overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
spec/slots.spec.sh:6:! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
spec/book_window.spec.sh:5:BOOKINGS=$t bash src/book.sh aoi "$far" 10:00 11:00 x >/dev/null 2>&1; [ $? = 2 ] || { echo "91 days ahead was accepted"; fail=1; }
spec/book_window.spec.sh:6:BOOKINGS=$t bash src/book.sh aoi "$near" 10:00 11:00 x >/dev/null 2>&1 || { echo "89 days ahead was rejected"; fail=1; }
#!/bin/bash
# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
mkdir -p var
s=0; for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
[ $s = 0 ] && echo "all specs pass"; exit $s

all specs pass
rc=0
 M .gitignore

